if '<div class="sensor-label">JJ-07</div>' not in text:
    text = text.replace('\n        </div>\n    </div>\n\n    <script>', '\n            <div class="sensor-label">JJ-07</div>\n\n        </div>\n    </div>\n\n    <script>')

script_start = text.find('    <script>')
if script_start != -1:
    new_script = "    <script>\n        const audioContext = new (window.AudioContext || window.webkitAudioContext)();\n        let oscillator = null;\n        let gainNode = null;\n        let continuousPanner = null;\n        let isActive = false;\n        let soundEnabled = true;\n        let continuousMode = false;\n        let calibrationOffset = { x: 0, y: 0 };\n        let lastSoundTime = 0;\n        const SOUND_INTERVAL = 180;\n\n        function createTone(frequency, volume = 0.1, options = {}) {\n            if (!soundEnabled) return;\n\n            const { type = 'sine', pan = 0 } = options;\n\n            if (continuousMode) {\n                if (!oscillator) {\n                    oscillator = audioContext.createOscillator();\n                    gainNode = audioContext.createGain();\n                    if (audioContext.createStereoPanner) {\n                        continuousPanner = audioContext.createStereoPanner();\n                        gainNode.connect(continuousPanner);\n                        continuousPanner.connect(audioContext.destination);\n                    } else {\n                        continuousPanner = null;\n                        gainNode.connect(audioContext.destination);\n                    }\n                    oscillator.connect(gainNode);\n                    oscillator.start();\n                }\n                oscillator.type = type;\n                oscillator.frequency.setValueAtTime(frequency, audioContext.currentTime);\n                if (continuousPanner) {\n                    continuousPanner.pan.setValueAtTime(Math.max(-1, Math.min(1, pan)), audioContext.currentTime);\n                }\n                gainNode.gain.setValueAtTime(volume, audioContext.currentTime);\n            } else {\n                const now = Date.now();\n                if (now - lastSoundTime < SOUND_INTERVAL) return;\n                lastSoundTime = now;\n\n                const osc = audioContext.createOscillator();\n                const gain = audioContext.createGain();\n                osc.type = type;\n                osc.frequency.value = frequency;\n                gain.gain.value = volume;\n\n                if (audioContext.createStereoPanner) {\n                    const panner = audioContext.createStereoPanner();\n                    panner.pan.value = Math.max(-1, Math.min(1, pan));\n                    osc.connect(gain);\n                    gain.connect(panner);\n                    panner.connect(audioContext.destination);\n                } else {\n                    osc.connect(gain);\n                    gain.connect(audioContext.destination);\n                }\n\n                osc.start();\n                gain.gain.exponentialRampToValueAtTime(0.01, audioContext.currentTime + 0.2);\n                osc.stop(audioContext.currentTime + 0.25);\n            }\n        }\n\n        function stopContinuousTone() {\n            if (!oscillator) return;\n            gainNode.gain.exponentialRampToValueAtTime(0.001, audioContext.currentTime + 0.1);\n            oscillator.stop(audioContext.currentTime + 0.12);\n            oscillator = null;\n            gainNode = null;\n            if (continuousPanner) {\n                continuousPanner.disconnect();\n                continuousPanner = null;\n            }\n        }\n\n        async function requestPermission() {\n            if (typeof DeviceOrientationEvent !== 'undefined' && typeof DeviceOrientationEvent.requestPermission === 'function') {\n                try {\n                    const permission = await DeviceOrientationEvent.requestPermission();\n                    if (permission === 'granted') {\n                        startSensor();\n                    } else {\n                        alert('センサーの使用許可が必要です');\n                    }\n                } catch (error) {\n                    console.error('Permission error:', error);\n                    alert('センサーアクセスエラー: ' + error.message);\n                }\n            } else {\n                startSensor();\n            }\n        }\n\n        function startSensor() {\n            if (isActive) return;\n            window.addEventListener('deviceorientation', handleOrientation, true);\n            isActive = true;\n            document.getElementById('status').textContent = 'センサー稼働中';\n            document.getElementById('status').classList.add('active');\n            const startBtn = document.getElementById('startBtn');\n            startBtn.textContent = 'センサー停止';\n            startBtn.onclick = stopSensor;\n        }\n\n        function stopSensor() {\n            window.removeEventListener('deviceorientation', handleOrientation, true);\n            isActive = false;\n            stopContinuousTone();\n            document.getElementById('status').textContent = 'センサー待機中...';\n            document.getElementById('status').classList.remove('active');\n            const startBtn = document.getElementById('startBtn');\n            startBtn.textContent = 'センサー開始';\n            startBtn.onclick = requestPermission;\n        }\n\n        function handleOrientation(event) {\n            const gamma = event.gamma - calibrationOffset.x;\n            const beta = event.beta - calibrationOffset.y;\n\n            const clampedGamma = Math.max(-45, Math.min(45, gamma));\n            const clampedBeta = Math.max(-45, Math.min(45, beta));\n\n            document.getElementById('angleX').textContent = gamma.toFixed(1) + '°';\n            document.getElementById('angleY').textContent = beta.toFixed(1) + '°';\n\n            const maxOffset = 140;\n            const bubbleX = (clampedGamma / 45) * maxOffset;\n            const bubbleY = (clampedBeta / 45) * maxOffset;\n\n            const bubble = document.getElementById('bubble');\n            bubble.style.transform = 	ranslate(calc(-50% + px), calc(-50% + px));\n\n            const totalTilt = Math.sqrt(gamma * gamma + beta * beta);\n            const tiltPercent = Math.min(100, (totalTilt / 45) * 100);\n            document.getElementById('tiltLevel').textContent = tiltPercent.toFixed(0) + '%';\n            document.getElementById('precisionFill').style.width = tiltPercent + '%';\n\n            if (soundEnabled) {\n                const absGamma = Math.abs(gamma);\n                const absBeta = Math.abs(beta);\n                const horizontalDominant = absGamma >= absBeta;\n\n                let freqBase;\n                let waveType;\n                let panValue = 0;\n\n                if (horizontalDominant) {\n                    freqBase = 420 + (gamma * 10);\n                    waveType = 'sawtooth';\n                    panValue = Math.max(-1, Math.min(1, gamma / 35));\n                } else {\n                    freqBase = 620 + (beta * 8);\n                    waveType = 'triangle';\n                }\n\n                const volume = Math.min(0.18, (totalTilt / 45) * 0.18);\n\n                if (totalTilt > 1) {\n                    createTone(freqBase, volume, { type: waveType, pan: panValue });\n                } else {\n                    stopContinuousTone();\n                }\n            }\n        }\n\n        function calibrate() {\n            if (!isActive) {\n                alert('先にセンサーを起動してください');\n                return;\n            }\n\n            window.addEventListener('deviceorientation', function calibrationHandler(event) {\n                calibrationOffset.x = event.gamma;\n                calibrationOffset.y = event.beta;\n                window.removeEventListener('deviceorientation', calibrationHandler, true);\n                alert('キャリブレーション完了');\n            }, { once: true });\n        }\n\n        function toggleSound() {\n            soundEnabled = !soundEnabled;\n            document.getElementById('soundToggle').classList.toggle('active');\n            if (!soundEnabled) {\n                stopContinuousTone();\n            }\n        }\n\n        function toggleContinuous() {\n            continuousMode = !continuousMode;\n            document.getElementById('continuousToggle').classList.toggle('active');\n            if (!continuousMode) {\n                stopContinuousTone();\n            }\n        }\n\n        document.getElementById('status').textContent = 'センサー待機中...';\n    </script>"
    text = replace_function(text, '    <script>', new_script)

